package com.paitrick.blog.tag.service; import com.paitrick.blog.tag.domain.Tag; import com.paitrick.blog.tag.dto.TagRequest; import com.paitrick.blog.tag.repository.TagMapper; import com.paitrick.blog.common.exception.BusinessException; import org.springframework.stereotype.Service; import java.util.*; @Service public class TagService{private final TagMapper m;public TagService(TagMapper m){this.m=m;}public List<Tag> all(){return m.all();}public Tag create(TagRequest r){var t=new Tag(null,r.name(),r.slug(),null,null);m.insert(t);return t;}public Tag update(long id,TagRequest r){if(m.byId(id)==null)throw new BusinessException("tag not found");var t=new Tag(id,r.name(),r.slug(),null,null);m.update(t);return m.byId(id);}public void delete(long id){if(m.delete(id)==0)throw new BusinessException("tag not found");}}
